de":-38.486687},{"source_sequence":226,"locality":"UMBUZEIRO 2","people_served":51,"latitude":-8.504703,"longitude":-38.494197},{"source_sequence":227,"locality":"URUBU","people_served":29,"latitude":-8.512406,"longitude":-38.150902},{"source_sequence":228,"locality":"VALE OURO","people_served":2,"latitude":-8.645098,"longitude":-38.599349},{"source_sequence":229,"locality":"VARJOTA","people_served":42,"latitude":-8.590915,"longitude":-38.392459},{"source_sequence":230,"locality":"VARZEA COMPRIDA 1","people_served":5,"latitude":-8.632,"longitude":-38.3895},{"source_sequence":231,"locality":"VARZEA COMPRIDA 2","people_served":60,"latitude":-8.641906,"longitude":-38.383985},{"source_sequence":232,"locality":"VARZEA DO ICO","people_served":12,"latitude":-8.294336,"longitude":-38.318224},{"source_sequence":233,"locality":"VARZEA DO ICO 2","people_served":22,"latitude":-8.287628,"longitude":-38.333743},{"source_sequence":234,"locality":"VARZEA REDONDA","people_served":24,"latitude":-8.288396,"longitude":-38.343963},{"source_sequence":235,"locality":"VASSOURAS","people_served":34,"latitude":-8.469082,"longitude":-38.014016},{"source_sequence":236,"locality":"VEADO","people_served":10,"latitude":-8.342514,"longitude":-38.413439},{"source_sequence":237,"locality":"VENEZA","people_served":14,"latitude":-8.67021,"longitude":-38.605796},{"source_sequence":238,"locality":"VILA DE AIRI","people_served":95,"latitude":-8.539695,"longitude":-38.193381},{"source_sequence":239,"locality":"VOLTINHA 1","people_served":5,"latitude":-8.595632,"longitude":-38.328702},{"source_sequence":240,"locality":"VOLTINHA 2","people_served":8,"latitude":-8.602111,"longitude":-38.334126},{"source_sequence":241,"locality":"VOLTINHA 3","people_served":18,"latitude":-8.608712,"longitude":-38.325656}]$army$::jsonb;
begin
  if not exists (
    select 1 from public.orgao_canais
    where id=v_channel and city_id=64 and nome='Abastecimento'
      and 'water_supply'=any(municipal_modules)
  ) then return; end if;

  if (select count(*) from public.pipa_tanks) <> 10
    or (select count(*) from public.pipa_tanks where channel_id=v_channel) <> 10
    or (select count(*) from public.pipa_requests where channel_id=v_channel) <> 19
    or (select count(*) from public.pipa_deliveries where channel_id=v_channel) <> 75
    or (select count(*) from public.pipa_routes where channel_id=v_channel) <> 3
    or (select count(*) from public.pipa_requests where tank_id in (select id from public.pipa_tanks where channel_id=v_channel)) <> 17
    or (select count(*) from public.pipa_deliveries where tank_id in (select id from public.pipa_tanks where channel_id=v_channel)) <> 74
  then raise exception 'Inventário de desenvolvimento mudou desde a cópia de segurança; importação cancelada.'; end if;

  select pm.user_id into v_actor
  from public.prefeituras p join public.prefeitura_membros pm on pm.prefeitura_id=p.id
  where p.city_id=64 and p.status='ativa' and pm.ativo and pm.papel='administrador'
  order by pm.user_id limit 1;
  if v_actor is null then raise exception 'Administrador municipal não encontrado para auditoria.'; end if;
  if jsonb_array_length(v_rows) <> 241 or
    (select sum(people_served) from jsonb_to_recordset(v_rows) as row(people_served integer)) <> 7056
  then raise exception 'Anexo não confere com 241 caixas e 7.056 pessoas.'; end if;

  update public.pipa_tanks set archived_at=now(),active=false,updated_at=now()
  where channel_id=v_channel and archived_at is null;
  get diagnostics v_count = row_count;
  if v_count <> 10 then raise exception 'Caixas arquivadas inesperadas: %',v_count; end if;

  update public.pipa_requests set status='cancelled'
  where channel_id=v_channel and tank_id in
    (select id from public.pipa_tanks where channel_id=v_channel and archived_at is not null)
    and status in ('pending','assigned','in_transit');
  update public.pipa_routes set cancelled=true where channel_id=v_channel and not cancelled;

  insert into public.pipa_tanks (
    channel_id,name,locality,address,latitude,longitude,
    capacity_liters,people_served,provider,responsible_name,
    responsible_document,responsible_phone,responsible_address,
    notes,active,created_by
  )
  select v_channel,'Caixa d’água · '||initcap(row.locality),
    row.locality,'',row.latitude,row.longitude,
    null,row.people_served,'exercito','Não informado',null,null,null,
    'Fonte: Anexo_Resposta_3511; sequência '||row.source_sequence,true,v_actor
  from jsonb_to_recordset(v_rows) as row(
    source_sequence integer,locality text,people_served integer,
    latitude double precision,longitude double precision
  ) order by row.source_sequence;
  get diagnostics v_count = row_count;
  if v_count <> 241 then raise exception 'Caixas importadas: % de 241',v_count; end if;
  if (select count(*) from public.pipa_tanks where channel_id=v_channel and archived_at is null and provider='exercito') <> 241
    or (select sum(people_served) from public.pipa_tanks where channel_id=v_channel and archived_at is null) <> 7056
  then raise exception 'Verificação final do inventário importado falhou.'; end if;
end $import$;

notify pgrst,'reload schema';
commit;
